have = {i['key'] for i in items}; n = 0
for d in D:
    key = 'cd57-' + d['id']
    if key in have: continue
    F = []
    for k, f in enumerate(d['fr']):
        o = ORIG.get((d['v'], f)); p = (T + f'orig/{o}.jpg') if o and os.path.exists(T + f'orig/{o}.jpg') else T + f"{d['v']}/f{f:03d}.jpg"
        im = Image.open(p).convert('RGB')
        fn = f"{d['id']}-{k + 1}.jpg"; tn = f"{d['id']}-{k + 1}-t.jpg"
        im.save(R + 'seed/import/' + fn, quality=90); t = im.copy(); t.thumbnail((420, 420)); t.save(R + 'seed/import/' + tn, quality=80)
        F.append({'file': fn, 'thumb': tn})
    items.append({'key': key, 'kind': 'doc', 'id': d['id'], 'files': F, 'data': {
        'title': d['title'], 'date': d['date'], 'place': 'Вороньки', 'src': src(d['v'], d['ark'], ', '.join(map(str, d['fr']))),
        'url': f"https://archium.cdiak.archives.gov.ua/file-viewer/{d['v']}", 'line': d['line'], 'text': d['text'], 'people': d['people'],
        'marks': [{'p': p, 'x': x, 'y': y, 'w': w, 'h': h} for p, x, y, w, h in d['marks']]}})
    n += 1
json.dump(m, open(R + 'seed/import/manifest.json', 'w'), ensure_ascii=False, indent=1)
print('додано', n)

